CREATE TABLE `jobs` (
	`id` text PRIMARY KEY NOT NULL,
	`organization_id` text,
	`title` text NOT NULL,
	`slug` text NOT NULL,
	`company_name` text NOT NULL,
	`company_logo_url` text,
