CREATE TABLE `reports` (
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`slug` text NOT NULL,
	`abstract` text NOT NULL,
	`pdf_r2_key` text,
	`tier_required` text DEFAULT 'pro' NOT NULL,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `social_assets` (
	`id` text PRIMARY KEY NOT NULL,
	`event_id` text,
	`article_id` text,
	`platform` text NOT NULL,
	`format` text NOT NULL,
	`status` text DEFAULT 'DRAFT' NOT NULL,
	`body` text NOT NULL,
	`media_urls` text,
	`scheduled_at` text,
	`idempotency_key` text NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`event_id`) REFERENCES `intelligence_events`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`article_id`) REFERENCES `articles`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `social_publications` (
	`id` text PRIMARY KEY NOT NULL,
	`asset_id` text NOT NULL,
	`platform` text NOT NULL,
	`external_post_id` text,
	`status` text NOT NULL,
	`attempts` integer DEFAULT 0 NOT NULL,
	`next_attempt_at` text,
	`error_message` text,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`asset_id`) REFERENCES `social_assets`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `source_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`source_id` text NOT NULL,
	`external_message_id` text NOT NULL,
	`content_hash` text NOT NULL,
	`raw_content` text NOT NULL,
	`normalized_content` text,
	`original_language` text,
	`parsed_entities` text,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`) ON UPDATE no action ON DELETE cascade
);
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_df1b16aa-b47','tg_vxunderground','89401','a1e1a2905a41f621a1f96d560791a122eccc888345a5e27f5c9132bb27c83774','CRITICAL ADVISORY: Threat actor APT29 observed weaponizing CVE-2026-1453 for remote execution delivering Cobalt Strike and Lumma stealer. Active C2 node located at 194.26.29.112 with binary payload SHA256 e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855 (T1190).','CRITICAL ADVISORY: Threat actor APT29 observed weaponizing CVE-2026-1453 for remote execution delivering Cobalt Strike and Lumma stealer. Active C2 node located at 194.26.29.112 with binary payload SHA256 e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855 (T1190).','en','{"cves":["CVE-2026-1453"],"ipv4s":["194.26.29.112"],"sha256s":["e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"],"md5s":[],"domains":[],"ttps":["T1190"],"actors":["APT29"],"malware":["Cobalt Strike","Lumma"]}','SUCCEEDED','2025-08-21T17:17:10.000Z','2026-08-21 17:17:28','2026-08-21 17:17:28');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_93f7cbb1-b08','tg_cvenotify','264937','c6f14f7fef76e3f90168f9760f247f22024cf5761f5c67f8c7106b10bf560256',replace('🚨 [CVE-2026-74583](https://git.kernel.org/stable/c/0e7a8cf8895b06d07c7311f028eba16ad742b9bc)\nIn the Linux kernel, the following vulnerability has been resolved:\n\nnet/sched: cls_route: fix fastmap use-after-free on filter\n\nThe route4 classifier maintains a 16-slot fastmap cache that stores raw\nstruct route4_filter pointers indexed by (id, iif). The reader\n(route4_classify) populates this cache via route4_set_fastmap() for every\nclassified packet that hits a filter. The writer (route4_delete,\nroute4_change) clears the cache via route4_reset_fastmap() before\nRCU-deferred kfree of the filter.\n\nThis creates a UAF race:\n 1. Reader walks the RCU-protected bucket chain, finds filter f\n 2. Writer unlinks f, calls route4_reset_fastmap(), then tcf_queue_work()\n 3. Reader calls route4_set_fastmap() and writes f into the cache\n    *after* the writer''s reset, caching a pointer about to be freed\n 4. After the RCU grace period, kfree(f) executes\n 5. Next classified packet on the same (id, iif) tuple hits the stale\n    fastmap entry and reads f->res from freed memory\n\nReproduced with an mdelay(100) accelerator in route4_set_fastmap() and a\nconcurrent add/delete stress test (provided by both zdi and Santosh).\nBoth triggered KASAN slab-use-after-free reports in the route4 fastmap\npaths.\n\nFix:\nIntroduce a per-filter boolean dying flag to suppress stale fastmap\nrepublishing by in-flight readers.\n\n🎖@cveNotify','\n',char(10)),'🚨 [CVE-2026-74583](https://git.kernel.org/stable/c/0e7a8cf8895b06d07c7311f028eba16ad742b9bc) In the Linux kernel, the following vulnerability has been resolved:  net/sched: cls_route: fix fastmap use-after-free on filter','en','{"cves":["CVE-2026-74583"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["git.kernel.org"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:24:12.000Z','2026-08-21 17:27:21','2026-08-21 17:27:21');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_fb6683e7-68c','tg_pentestingnews','76001','420b99eb11f132328f24c66667f1a1e124d7ff6b8d4895f7a4a58ba98df73c8e',replace('[ ](https://thecyberexpress.com/microsoft-entra-id-cve-2026-69836-exploited/)Microsoft Says CVSS 10.0 Entra ID Code Execution Flaw Was Exploited Before Server-Side Fix\n\nhttps://thecyberexpress.com/microsoft-entra-id-cve-2026-69836-exploited/','\n',char(10)),'[ ](https://thecyberexpress.com/microsoft-entra-id-cve-2026-69836-exploited/)Microsoft Says CVSS 10.0 Entra ID Code Execution Flaw Was Exploited Before Server-Side Fix  https://thecyberexpress.com/microsoft-entra-id-cve-2026-69836-exploited/','en','{"cves":["CVE-2026-69836"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["thecyberexpress.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T15:42:12.000Z','2026-08-21 17:27:24','2026-08-21 17:27:24');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_99c23801-bc0','tg_blueteamalerts','21471','3059fb7e00da93189a5b9c30f8972477dfa235ee3eab562fef52f57d2efa2199',replace('**Reverse-engineering Find My People to stalk  ̶m̶y̶ ̶e̶x̶  a friend, cause I can**\nhttps://ift.tt/iCoMnft\n\nDiscuss on Reddit: https://ift.tt/gKp8IVZ\n@blueteamalerts','\n',char(10)),'Reverse-engineering Find My People to stalk  ̶m̶y̶ ̶e̶x̶  a friend, cause I can https://ift.tt/iCoMnft  Discuss on Reddit: https://ift.tt/gKp8IVZ','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["ift.tt"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:17:28.000Z','2026-08-21 17:27:25','2026-08-21 17:27:25');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_cfbcde43-8d6','tg_aptreports','31751','615905475c5ac2887fd731e4f0b6b7e6ee12638e97ad09ced65cc659e50f7551',replace('#ParsedReport #ChatGPT #Translated\n**Autotext**: (TI Report Analyser + ChatGPT + Auto Translate)\n\n------\nЗашифрованный JavaScript-лоадер декодирует и выполняет встроенный PowerShell-пэйлоад. Скрипт записывает файлы в `%TEMP%`, создает ярлык для выполнения, устанавливает закрепление на основе реестра в `HKCU` и `HKLM`, а затем запускает последующий этап PowerShell, связанный с RAT Remcos.\n-----\n\nВ отчете анализируется цепочка атаки, включающая троянскую программу удаленного доступа Remcos (RAT). Изначальный файл JavaScript был зашифрован, и анализ его исходного кода выявил встроенную Base64-кодированную полезную нагрузку. Декодирование содержимого Base64 привело к созданию скрипта PowerShell, что указывает на использование PowerShell в качестве основного механизма выполнения.\n\nРаскодированный скрипт создает объекты ActiveX в Windows для взаимодействия с файловой системой, включая создание папок и запись файлов. Он сохраняет PowerShell-скрипт в директории `%TEMP%` и настраивает ярлык Windows для выполнения этого скрипта через PowerShell. Это обеспечивает механизм запуска полезной нагрузки, потенциально маскируя выполнение через файл ярлыка.\n\nСкрипт также обеспечивает закрепление, изменяя связанные с запуском записи реестра в разделах текущего пользователя и локальной машины. В частности, он создает команды запуска на основе реестра в разделах `HKCU` и `HKLM`, которые вызывают тот же скрипт PowerShell. Эти изменения позволяют вредоносному скрипту выполняться автоматически при входе пользователя в систему или при запуске системы, в зависимости от разрешений и конфигурации системы.\n\nФункция с именем `launchScript` отвечает за запуск выполнения PowerShell-полезной нагрузки. Наблюдаемые команды, таким образом, поддерживают многоэтапный процесс: обфусцированный JavaScript декодирует встроенный PowerShell-скрипт, скрипт создает файлы и объекты ярлыков, закрепление настраивается через ключи реестра, и запускается финальный PowerShell-скрипт. Затем анализ выявляет еще один PowerShell-скрипт как часть последующего этапа, хотя его поведение не описано в предоставленном отрывке.','\n',char(10)),'ParsedReport ChatGPT Translated Autotext: (TI Report Analyser + ChatGPT + Auto Translate)  ------','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:27:16.000Z','2026-08-21 17:27:27','2026-08-21 17:27:27');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_d769a8fe-0bc','tg_xakep_ru','19928','32a2118b2b2ba67016737debedd144235794a2e9a76d14307eaa5d1bcf41f6ad',replace('**Утечка кадров GTA VI используется для раскрутки криптотокена**\n\nПользователь с ником CyberLeek опубликовал новую партию утечек из GTA VI, сопроводив их тикером собственного криптотокена $CYBERLEEK, который он продвигает в рамках некоего «секретного проекта». Материалы включали детали карты GTA VI и кадры геймплея в открытом мире, однако на момент написания статьи они уже были недоступны в X: их удалили после того, как юристы Rockstar Games подали...\n\nhttps://xakep.ru/2026/08/21/cyberleek-token/','\n',char(10)),'Утечка кадров GTA VI используется для раскрутки криптотокена  Пользователь с ником CyberLeek опубликовал новую партию утечек из GTA VI, сопроводив их тикером собственного криптотокена $CYBERLEEK, который он продвигает в рамках некоего «секретного проекта». Материалы включали детали карты GTA VI и кадры геймплея в откры','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["xakep.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T16:33:58.000Z','2026-08-21 17:27:29','2026-08-21 17:27:29');
