INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_d1f49462-ece','tg_thehackernews','9869','d0601bc91878c9d5a4131792e33396741835d9d05e1a7b33ba19b29e48bb63f3',replace('‼️ Attackers can weaponize Defender’s own signed driver to delete security software at boot.\n\nBTR.sys runs from Ring 0 before Defender’s user-mode services start. Check Point showed it deleting the full Defender stack on Windows 11 25H2 with Tamper Protection enabled.\n\nSee how it works: [https://thehackernews.com/2026/08/microsoft-defenders-own-driver-can-be.html](https://thehackernews.com/2026/08/microsoft-defenders-own-driver-can-be.html)','\n',char(10)),'‼️ Attackers can weaponize Defender’s own signed driver to delete security software at boot.  BTR.sys runs from Ring 0 before Defender’s user-mode services start. Check Point showed it deleting the full Defender stack on Windows 11 25H2 with Tamper Protection enabled.','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["BTR.sys","thehackernews.com","microsoft-defenders-own-driver-can-be.html"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T16:04:14.000Z','2026-08-21 17:35:49','2026-08-21 17:35:49');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_fae55cc0-d86','tg_thehackernews','9868','6f49bb604771dfb88ca27c4fc8a7837026c35da82661c69b9e84a5ddc933902a',replace('⚠️ Android car head units are getting malware through built-in updaters.\n\nAttackers abused DoFun’s update channel to deliver malware for ad fraud and proxy botnet activity. It can also download and run arbitrary code.\n\nFull details: [https://thehackernews.com/2026/08/android-car-malware-spreads-through.html](https://thehackernews.com/2026/08/android-car-malware-spreads-through.html)','\n',char(10)),'⚠️ Android car head units are getting malware through built-in updaters.  Attackers abused DoFun’s update channel to deliver malware for ad fraud and proxy botnet activity. It can also download and run arbitrary code.','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["thehackernews.com","android-car-malware-spreads-through.html"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T15:43:23.000Z','2026-08-21 17:35:50','2026-08-21 17:35:50');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_93014f51-fbb','tg_cvenotify','264936','c0dd03d55f346e6f2283aa6bc49445bd864bbd727f93696c3f176ff25aba57aa',replace('🚨 [CVE-2026-74582](https://git.kernel.org/stable/c/03390aa32e669cc4ecd7d34108e2e1afc13d689d)\nIn the Linux kernel, the following vulnerability has been resolved:\n\npacket: use consistent hard_header_len in non-ring send paths\n\npacket_snd() reads dev->hard_header_len multiple times while allocating\nand constructing an skb. Device reconfiguration can change this value\nconcurrently, for example through bonding device type changes.\n\nFor SOCK_RAW, packet_snd() can save a larger value in reserve and later\nallocate headroom using a smaller value. Moving skb->data back by reserve\nthen places it before skb->head, and the following copy from userspace can\nattempt an out-of-bounds write.\n\npacket_sendmsg_spkt() has the same issue because it calculates its\nreservation and header offset from separate reads before dropping the RCU\nread lock to allocate the skb.\n\nAdd LL_RESERVED_SPACE_EX() for callers that already saved a header length.\nRead hard_header_len once in packet_snd() and use it for allocation and\nconstruction. In packet_sendmsg_spkt(), preserve the allocation-time value\nthrough the device lookup retry.\n\nThe separate SOCK_DGRAM consistency problem between hard_header_len and\nheader_ops->create is not addressed here.\n\n🎖@cveNotify','\n',char(10)),'🚨 [CVE-2026-74582](https://git.kernel.org/stable/c/03390aa32e669cc4ecd7d34108e2e1afc13d689d) In the Linux kernel, the following vulnerability has been resolved:  packet: use consistent hard_header_len in non-ring send paths','en','{"cves":["CVE-2026-74582"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["git.kernel.org"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:24:07.000Z','2026-08-21 17:35:53','2026-08-21 17:35:53');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_0bc30114-0e6','tg_pentestingnews','76000','bf623930763a6349fe1476be4bd9ac1610ae7ed4f63fc52dbecaeda3857d421a',replace('[ ](https://thecyberexpress.com/weekly-roundup-tax-breach-ai-gitlab-flaw/)The Cyber Express Weekly Roundup: Tax Data Breach, AI Security Risks, and Critical GitLab Flaw\n\nhttps://thecyberexpress.com/weekly-roundup-tax-breach-ai-gitlab-flaw/','\n',char(10)),'[ ](https://thecyberexpress.com/weekly-roundup-tax-breach-ai-gitlab-flaw/)The Cyber Express Weekly Roundup: Tax Data Breach, AI Security Risks, and Critical GitLab Flaw  https://thecyberexpress.com/weekly-roundup-tax-breach-ai-gitlab-flaw/','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["thecyberexpress.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T14:47:27.000Z','2026-08-21 17:35:55','2026-08-21 17:35:55');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_7ebdf9ee-465','tg_blueteamalerts','21470','1ac95650927626f8fa646251e72936a8038f45316df10134142ab0c3d0b931b9',replace('**FTP Banners: The New Dead Drop Resolver Delivering Novel RATs**\nSharing some detection angles from recent work on FTP banners being abused as dead drop resolvers, based on two RAT families we''ve been calling E4del and PINHOLE.On the network side, the interesting gap is that most orgs don''t inspect FTP banner content at all; they just don''t expect port 21 to be a delivery mechanism. Worth watching for LNK-spawned processes or shell scripts reaching out to external FTP endpoints, and flagging banners that contain encoded PowerShell or WebDAV-sourced rundll32 calls.On the endpoint side, for PINHOLE specifically:→ Check for writes to %USERPROFILE%\Downloads\desktop.ini:bt or desktop.ini:ek  that''s where it''s stashing config data in ADS→ Suspended ApplicationFrameHost.exe processes getting an APC queued immediately after creation (NtQueueApcThread) is a strong signal for the injection technique it uses→ Page permission toggling between PAGE_READWRITE and PAGE_EXECUTE_READ, paired with trapped 0xC0000005 exceptions via VEH, is the fingerprint of its shellcode fluctuation approachA few host-level artifacts worth adding to hunt queries: u.cmd, calc.cab, and calc_runner.cmd showing up in %TEMP%, signature mismatches on Discord.exe tied to a modified app.asar, and a Load value under HKCU\Software\Microsoft\Windows NT\CurrentVersion\Windows.Happy to go deeper on any of this if people are building detections around it.[https://hubs.la/Q04tQxV30](https://hubs.la/Q04tQxV30) \n\nDiscuss on Reddit: https://ift.tt/nmehE5v\n@blueteamalerts','\n',char(10)),'FTP Banners: The New Dead Drop Resolver Delivering Novel RATs Sharing some detection angles from recent work on FTP banners being abused as dead drop resolvers, based on two RAT families we''ve been calling E4del and PINHOLE.On the network side, the interesting gap is that most orgs don''t inspect FTP banner content at a','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["PINHOLE.On","calls.On","desktop.ini","ApplicationFrameHost.exe","u.cmd","calc.cab","Discord.exe","app.asar","Windows.Happy","hubs.la","ift.tt"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T15:17:02.000Z','2026-08-21 17:35:56','2026-08-21 17:35:56');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_5ccbb80a-a52','tg_aptreports','31764','a117482d161c9e0d2b044d5c7dda6dd3933e09b380852a0c5efe014bbdfa6807',replace('#ParsedReport #ChatGPT #Translated\n**Autotext**: (TI Report Analyser + ChatGPT + Auto Translate)\n\n------\nSilkParasite — это кампания шпионажа, связанная с Китаем, направленная против правительственных организаций и организаций, занимающихся экономической политикой, в Центральной Азии и на Южном Кавказе. В основном она использовала фишинговые документы Office и архивы, защищенные паролем, для развертывания модульных RAT с подгрузкой DLL. Вредоносное ПО поддерживало выполнение на основе плагинов, кражу учетных данных и Регистрация нажатий клавиш, доступ к процессам и буферу обмена, закрепление через запланированные задачи и скрытую C2 через Google Drive, заголовки HTTP и выделенные передатчики.\n-----\n\nSilkParasite — это кластер шпионской активности, связанный с Китаем, нацеленный на правительственные организации и организации, занимающиеся экономической политикой, в Центральной Азии и на Южном Кавказе. Исследователи выявили операцию после обнаружения заражения в правительственной структуре Центральной Азии в октябре 2025 года. В рамках кампании использовались семь модульных семейств RAT, включая SpiceRAT, DriveSilkRAT, CookiETagRAT, BloodAlchemy, NomadRAT, GoginRAT и NodeEdgeRAT. Приписывание операции одной конкретной названной группе не подтверждается, однако связи с SpiceRAT, ассоциированным с SneakyChef, инфраструктурой China Unicom, региональным таргетингом и общим инструментарием, связанным с Китаем, указывают на среднюю уверенность в участии сторон, связанных с Китаем.\n\nПервоначальный доступ осуществлялся преимущественно посредством целевого фишинга с использованием электронных писем, содержащих вредоносные документы Microsoft Office. Часть приманок доставлялась в архивах RAR, защищённых паролем, при этом пароль указывался в тексте письма для обхода сканирования шлюзов и песочниц. Документы имитировали министерства и организации, связанные с государственными структурами Узбекистана, Туркменистана, Кыргызстана, Таджикистана, Казахстана и Грузии. Макросы разворачивали цепочки подгрузки DLL через подписанные приложения и перед выполнением проверяли наличие процесса `avp.exe` антивируса Kaspersky. Операторы часто сочетали легитимные подписанные исполняемые файлы с вредоносными DLL, включая бинарные файлы Calibre, ABBYY FineReader, Quick Heal, Windows Defender и Mp3tag.\n\nБольшинство внедренных модулей использовали модульные архитектуры и загружали плагины по требованию, что уменьшало их начальный размер и позволяло изменять функциональность без замены основного ВПО. DriveSilkRAT являлся основным оперативным бэкдором, опрашивая общую папку Google Drive для получения задач, выполняя загруженные .NET-плагины в памяти и загружая результаты через тот же сервис. Было обнаружено около 65 идентификаторов жертв, хотя аппаратные идентификаторы могут представлять собой дубликаты систем. CookiETagRAT скрывал команды в заголовках HTTP `Cookie` и `ETag`, тогда как SpiceRAT использовал закрепление через запланированные задачи, хешированное разрешение API и цепочку подгрузки на основе Calibre.\n\nBloodAlchemy, связанный с семейством троянских программ ShadowPad и Deed RAT, использовал HalosGate, аппаратные точки останова и обработчики векторных исключений для обхода хуков пользовательского режима API. Он выполнял полезную нагрузку через `EnumTimeFormatsEx` и содержал плагины для имперсонации, выполнения процессов, регистрации содержимого буфера обмена и регистрации нажатий клавиш. NomadRAT и GoginRAT разделяли коммуникацию с C2 на выделенные компоненты-передатчики и поддерживали выполнение на основе плагинов. NodeEdgeRAT представлял собой зашифрованный JavaScript-имплант, запускаемый встроенным временем выполнения Node.js, с возможностями, встроенными непосредственно в скрипт, и закреплением через запланированную задачу с именем `SysEdgeUpdateTaskMachineCore`. Несколько образцов также содержали артефакты разработки, такие как заполнители ключей шифрования и оставшиеся тестовые функции.','\n',char(10)),'ParsedReport ChatGPT Translated Autotext: (TI Report Analyser + ChatGPT + Auto Translate)  ------','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["avp.exe","Node.js"],"ttps":[],"actors":[],"malware":["ShadowPad"]}','SUCCEEDED','2026-08-21T17:29:04.000Z','2026-08-21 17:36:00','2026-08-21 17:36:00');
