INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_856a0b5e-1b6','tg_malwr','10130','cd97a7834818306ca271026e92e6da5d97713815d4fb79db15f94a8551340abd',replace('**CNCMachineRMS C2 Protocol**\n\nThis post describes the binary command-and-control (C2) protocol used by CNCMachineRMS, a recently identified remote access trojan (RAT). We cover how the protocol was discovered, how its infrastructure was identified, and how network defenders can detect it. Background We have been tracking a previ...\n\nhttps://www.netresec.com/?page=Blog&month=2026-08&post=CNCMachineRMS-C2-Protocol\n\n\n🎖@malwr','\n',char(10)),'CNCMachineRMS C2 Protocol  This post describes the binary command-and-control (C2) protocol used by CNCMachineRMS, a recently identified remote access trojan (RAT). We cover how the protocol was discovered, how its infrastructure was identified, and how network defenders can detect it. Background We have been tracking','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.netresec.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T16:39:20.000Z','2026-08-21 17:36:04','2026-08-21 17:36:04');
