INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_6628e73d-894','tg_xakep_ru','19929','836ca94a07e4b39ea6501a4395bd35e30304568e73b2dab79c19c6c5678e3587',replace('**Популярный пакет arrayref в Crates[.]io заразили инфостилером**\n\nЗлоумышленники скомпрометировали аккаунт мейнтейнера сразу нескольких популярных Rust-пакетов и опубликовали вредоносные версии arrayref, internment и append-only-vec. Малварь автоматически запускалась во время сборки проекта.\n\nhttps://xakep.ru/2026/08/21/arrayref-stealer/','\n',char(10)),'Популярный пакет arrayref в Crates[.]io заразили инфостилером  Злоумышленники скомпрометировали аккаунт мейнтейнера сразу нескольких популярных Rust-пакетов и опубликовали вредоносные версии arrayref, internment и append-only-vec. Малварь автоматически запускалась во время сборки проекта.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["xakep.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:35:24.000Z','2026-08-21 17:36:07','2026-08-21 17:36:07');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_b65211d1-f34','tg_whackdoor','30725','d72a4f8c044ca6229e417c488d080b035b6593f4f052b066cbbb99ec4e2eb1f0',replace('⚡️ **Telegram удалил канал хакера Cyberleek** — это он сливает **GTA VI**\n\nRockstar начали охоту\n\n👍 [Бэкдор](https://t.me/whackdoor?erid=2VtzquZvQkb)','\n',char(10)),'⚡️ Telegram удалил канал хакера Cyberleek — это он сливает GTA VI  Rockstar начали охоту','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:21:18.000Z','2026-08-21 17:36:09','2026-08-21 17:36:09');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_6aa3cc53-cdb','tg_searchack','2941','55966f7f97d7502791a6a766e0c0db571462d193c698e526659d30034dd7e361',replace('📂 **pyWhat - Швейцарский нож для анализа любых данных**\n\nКогда последний раз вы сталкивались с загадочной строкой вроде 0x52908400098527886E0F7030069857D2E4169EE7и тратили время на поиски, что же это такое? А если таких строк сотни? pyWhat решает эту проблему одним махом — просто спросите у него «что это?».\n\n**pyWhat** – это Python-инструмент для автоматического распознавания структурированных данных в тексте, файлах и сетевых дампах.\n\n— Довольно интересный инструмент именно для **OSINT, malware analysis, DFIR, bug bounty и автоматического извлечения IOC**.\n\n🗄 Читать статью – [линк](https://devtrends.ru/python/bee-san-pywhat).\n🗄 Репозиторий на GitHub – [линк](https://github.com/bee-san/pyWhat).\n\n**//**[** Не хакинг, а ИБ**](https://max.ru/searchack)','\n',char(10)),'📂 pyWhat - Швейцарский нож для анализа любых данных  Когда последний раз вы сталкивались с загадочной строкой вроде 0x52908400098527886E0F7030069857D2E4169EE7и тратили время на поиски, что же это такое? А если таких строк сотни? pyWhat решает эту проблему одним махом — просто спросите у него «что это?».','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["devtrends.ru","max.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:25:02.000Z','2026-08-21 17:36:12','2026-08-21 17:36:12');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_5186956d-c7f','tg_searchack','2940','8bdae538ef140af201b62cc350e4f4445af2766bde2d573f7999df1c85d3c72a',replace('📸 **Хакеры взломали 14 500 камер Dahua всего за 35 дней**\n\nИБ-исследователи обнаружили масштабную кампанию [**CameraSwarm**](https://hunt.io/blog/operation-cameraswarm-dahua-cameras-compromised)**, в рамках которой хакеры взломали уже 14 530 IP-камер Dahua**. \n\nПо словам специалистов, атаки длились как минимум 35 дней (с 17 июня по 22 июля 2026 года), и большинство подтвержденных жертв находятся на территории **России и Украины**.\n\n— Аналитики Hunt.io пишут, что **обнаружили вредоносную активность случайно**: оператор CameraSwarm оставил без защиты рабочую директорию на HTTP-сервере. \n\n🗄 Источник – [линк](https://xakep.ru/2026/08/20/cameraswarm/).\n\n**//**[** Не хакинг, а ИБ**](https://max.ru/searchack)','\n',char(10)),'📸 Хакеры взломали 14 500 камер Dahua всего за 35 дней  ИБ-исследователи обнаружили масштабную кампанию [CameraSwarm](https://hunt.io/blog/operation-cameraswarm-dahua-cameras-compromised), в рамках которой хакеры взломали уже 14 530 IP-камер Dahua.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["hunt.io","Hunt.io","xakep.ru","max.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-20T19:00:01.000Z','2026-08-21 17:36:13','2026-08-21 17:36:13');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_82835df8-1cf','tg_seclabnews','18077','4ea91e777d5c49f68b5321d17c1e0c1a5c474308d3bfc70f262002077587aa35',replace('**Linux притворился устройством Apple и получил доступ к Find My**\n\nApple официально не дает Linux доступ к геопозиции людей в Find My, но 22-летний исследователь Zerotistic [нашел способ](https://www.securitylab.ru/news/576305.php) обойти платформенное ограничение. Меньше чем за неделю он зарегистрировал Linux-компьютер в инфраструктуре Apple как совместимое устройство и получил координаты человека, который заранее разрешил владельцу Apple Account видеть свое местоположение.\n\nПросто войти в Apple Account оказалось недостаточно. Linux пришлось провести через внутреннюю систему регистрации устройств Apple, получить сертификаты IDS и APNs, заявить поддержку сервисов Find My и зарегистрировать ключи для защищенного обмена. После этого серверы Apple признали самодельный клиент устройством, способным принимать сообщения Find My. Затем исследователь запросил ключ уже действующего обмена геопозицией и через SearchParty получил зашифрованные координаты, которые расшифровал прямо на Linux.\n\nСледить таким способом за кем угодно нельзя. Linux видит только людей, которые раньше сами поделились геопозицией с владельцем учетной записи. Зато эксперимент наглядно показал, что Find My People технически вполне способен работать за пределами экосистемы Apple. Linux здесь мешала не неспособность обработать данные, а необходимость убедить серверы Apple признать компьютер подходящим устройством.\n\n#Apple #FindMy #Linux\n@SecLabNews','\n',char(10)),'Linux притворился устройством Apple и получил доступ к Find My  Apple официально не дает Linux доступ к геопозиции людей в Find My, но 22-летний исследователь Zerotistic [нашел способ](https://www.securitylab.ru/news/576305.php) обойти платформенное ограничение. Меньше чем за неделю он зарегистрировал Linux-компьютер в','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.securitylab.ru","576305.php"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T15:04:12.000Z','2026-08-21 17:36:15','2026-08-21 17:36:15');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_c6f4283b-0bd','tg_seclabnews','18076','82112426da012299d677d9e04ae5e8bd1cd9e0eca5e9fdd1ddc18dfcc355ccf1',replace('**В Москве пройдет фестиваль о кибербезопасности и технологических рисках**\n\nКак атака на предпринимателя может превратиться в проблему для всей компании, какие ошибки в IT-инфраструктуре стоят бизнесу денег и как малые компании сталкиваются с последствиями взломов? Эти темы разберут 27 августа на CyberLink фесте в московском Кибердоме.\n\nВ программе заявлены дискуссии о кибербезопасности, технологических рисках, устойчивости IT-систем, DDoS-атаках и последствиях простоев производства. Отдельную сессию посвятят реальным атакам на малый бизнес, способам проникновения злоумышленников и восстановлению после инцидентов.\n\nНа фестивале также пройдет питч-сессия четырех стартапов в сфере кибербезопасности. Среди заявленных участников представители Timepad, «Будь Здоров», «Три сестры», Eggsellent, nōtem, технологических компаний и ИБ-сообщества. SecurityLab выступит партнером CyberLink феста.\n\nМероприятие [пройдет ](https://www.securitylab.ru/news/576336.php)27 августа.\n\n#CyberLink #Кибербезопасность #SecurityLab\n@SecLabNews','\n',char(10)),'В Москве пройдет фестиваль о кибербезопасности и технологических рисках  Как атака на предпринимателя может превратиться в проблему для всей компании, какие ошибки в IT-инфраструктуре стоят бизнесу денег и как малые компании сталкиваются с последствиями взломов? Эти темы разберут 27 августа на CyberLink фесте в московс','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.securitylab.ru","576336.php"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T13:02:12.000Z','2026-08-21 17:36:16','2026-08-21 17:36:16');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_f9ee99ce-1e2','tg_anti_malware','23212','ef57515ce1a618d60d0c86c06a4f175e1ac607672e96197fc30ab2930643489d',replace('⚡️**ФИНАЛЬНАЯ СЕРИЯ**! **Сериал-эксперимент про фишинг**\n\nУ нас была поддержка генерального директора, редакции и компании Phishman. Мне кажется, мы сделали всё идеально\nОлеся Афанасьева, руководитель продюсерского центра AM Live.\n\nКажется, про фишинг сегодня знают все, но компании по-прежнему взламывают одним и тем же способом через письмо в почте или сообщение в мессенджере. \n\n**Мы **— **AM Live, медиа о технологиях и кибербезопасности, вместе с компанией Phishman решили не разбирать чужие истории, а провести эксперимент над собой.** \n\nМы отправили сотрудникам фишинговые письма, провели обучение и повторную проверку. \n\nВ этом сериале мы хотим понять, можно ли всего за 3 недели изменить то, как люди принимают решение в момент атаки, или даже после обучения привычка оказывается сильнее знаний и технологий.\n\n**Пятая серия - Security Awareness работает? **\n\n📺 [VK](https://vkvideo.ru/video-21732035_456242250?pl=-21732035_31) 📺 [YouTube](https://youtu.be/qlNsSp2-VVo?si=lihxw26CF26s3d8f) 📺 [RuTube](https://rutube.ru/video/private/9e2f37055a5f34e745a223219e3b43ee/?p=1O94DowTs6QGTnNfD4JRKA)','\n',char(10)),'⚡️ФИНАЛЬНАЯ СЕРИЯ! Сериал-эксперимент про фишинг  У нас была поддержка генерального директора, редакции и компании Phishman. Мне кажется, мы сделали всё идеально Олеся Афанасьева, руководитель продюсерского центра AM Live.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":["9e2f37055a5f34e745a223219e3b43ee"],"domains":["vkvideo.ru","youtu.be","rutube.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:01:41.000Z','2026-08-21 17:36:18','2026-08-21 17:36:18');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_79f48bf3-cf7','tg_anti_malware','23211','2aa4a1ed43be8ffb381c1003f4ff13d61ff3712dcf75b563f4f424b9764b3cd0',replace('[**Супер-ИИ для взлома пока не появился, но атаки уже поставили на конвейер**](https://www.anti-malware.ru/news/2026-08-21-124606/51143)\n\nИскусственный интеллект пока не научился самостоятельно изобретать волшебные способы взлома любой системы. Зато он уже помогает злоумышленникам автоматизировать известные атаки и запускать их сразу против множества организаций, заявил руководитель BI.ZОNЕ Threat Intelligence Олег Скулкин на конференции OFFZONE 2026.\n\n🔥 [AM Live](https://t.me/anti_malware)','\n',char(10)),'[Супер-ИИ для взлома пока не появился, но атаки уже поставили на конвейер](https://www.anti-malware.ru/news/2026-08-21-124606/51143)  Искусственный интеллект пока не научился самостоятельно изобретать волшебные способы взлома любой системы. Зато он уже помогает злоумышленникам автоматизировать известные атаки и запуска','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.anti-malware.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T14:22:40.000Z','2026-08-21 17:36:18','2026-08-21 17:36:18');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_444be7d3-85c','tg_lab_hack','1937','94004874fa004e063a5b0e11e2641bcc26ba75af3d7cb40c57d38d067f9d4b62',replace('🖥 **Репозиторий: GhostTrack — инструмент для OSINT-разведки, геолокации и сбора информации об IP-адресах и номерах телефонов**\n\n**GhostTrack** — это консольная утилита на языке Python, предназначенная **для автоматизации сбора географических и сетевых данных из открытых источников**.\n\n— Инструмент позволяет извлекать общедоступные метаданные о сетевых провайдерах, операторах связи, географическом расположении IP-адресов и кодах стран, помогая аналитикам и исследователям безопасности проводить первичную пассивную разведку.\n\n⏺ [**Ссылка на GitHub**](https://github.com/HunxByts/GhostTrack)\n\n**#OSINT**** ****#Recon**** ****#IP**** ****#Python**** ****#Investigation**** | **[**Лаборатория хакера**](https://max.ru/lab_hack)','\n',char(10)),'🖥 Репозиторий: GhostTrack — инструмент для OSINT-разведки, геолокации и сбора информации об IP-адресах и номерах телефонов  GhostTrack — это консольная утилита на языке Python, предназначенная для автоматизации сбора географических и сетевых данных из открытых источников.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["max.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T16:09:32.000Z','2026-08-21 17:36:19','2026-08-21 17:36:19');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_cb9f2c9b-b8c','tg_lab_hack','1936','cb1048efec5893b1864811e057e9bb3ee00184e7e59105e61ec5abe9a7d96086',replace('📖 **Книга: «Linux в действии» — Дэвид Клинтон**\n\nЭто практическая книга по **администрированию Linux**, ориентированная не столько на изучение команд, сколько на решение реальных задач.\n\nДля cybersecurity эта книга интересна тем, что формирует **Linux-фундамент**, без которого сложно нормально заниматься пентестингом, malware analysis, DevSecOps или эксплуатацией инфраструктуры.\n\n**Отдельная глава посвящена защите веб-сервера, а ещё одна** — обеспечению безопасности сетевых соединений через VPN/DMZ. \n\n⏺ [**Ссылка на книгу**](https://max.ru/lab_hack/AaAf2tTacmQ)\n\n**#Book**** ****#Linux**** ****#Network**** ****#SSH**** ****#Web**** ****#Firewall**** ****#Admin**** ****#Pentest**** | **[**Лаборатория хакера**](https://max.ru/lab_hack)','\n',char(10)),'📖 Книга: «Linux в действии» — Дэвид Клинтон  Это практическая книга по администрированию Linux, ориентированная не столько на изучение команд, сколько на решение реальных задач.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["max.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-20T15:47:35.000Z','2026-08-21 17:36:20','2026-08-21 17:36:20');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_11ec4416-f04','tg_cyber_cabb','7289','c9f4db8be5c9da74391a1b936568e15297f8c9284d34b4f92ff5e19326e41dc8',replace('**Саморазвивающимся AI-агентам нужны отдельные правила кибербезопасности — эксперты Сбера **[**сформулировали**](https://www.gazeta.ru/social/news/2026/08/21/29151643.shtml)** пять базовых мер защиты таких систем.**\n\nРечь об агентах, которые способны самостоятельно обновлять память, добавлять навыки и менять собственный код. Исследование показало: даже защищённая AI-модель не исключает рисков на уровне самого агента и среды, в которой он работает.\n\nВ Сбере предлагают изолировать агентов и их доступы, разделять среды разработки и эксплуатации, а защитные механизмы выносить за пределы исполняемого кода. Новые навыки и инструменты должны проходить проверку перед добавлением в корпоративный реестр, а сгенерированный агентом код — запускаться в песочнице без доступа к сети и с ограниченными ресурсами.\n\nПри этом в рабочей среде с чувствительными данными возможность саморазвития агента предлагается полностью отключать. Изменения могут создаваться в отдельном контуре, но переходить в эксплуатацию — только после проверок безопасности.\n\nРекомендации подготовлены на основе обновлённой «Модели угроз кибербезопасности AI Сбера», которая систематизирует 37 угроз и 51 способ их реализации. Сама модель опубликована на портале «Кибрарий» и находится в открытом доступе — использовать её могут российские государственные и частные организации.','\n',char(10)),'Саморазвивающимся AI-агентам нужны отдельные правила кибербезопасности — эксперты Сбера [сформулировали](https://www.gazeta.ru/social/news/2026/08/21/29151643.shtml) пять базовых мер защиты таких систем.  Речь об агентах, которые способны самостоятельно обновлять память, добавлять навыки и менять собственный код. Иссле','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.gazeta.ru","29151643.shtml"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T16:26:48.000Z','2026-08-21 17:36:22','2026-08-21 17:36:22');
