INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_e839d631-2e2','tg_cibsecurity','90533','51b2b6ef7877f2518171e60f2070a89e88291bfa6ff0c3c067b4c2ed86a8b50b',replace('🕵️‍♂️ **Calling on Cyber Pros to Help Defend City Hall** 🕵️‍♂️\n\n`Government agencies with smaller budgets need support  and here''s how you can help.`\n\n📖 [Read more.](https://www.darkreading.com/cyber-risk/calling-on-cyber-pros-to-help-city-hall)\n\n🔗 Via "__Dark Reading__"\n\n----------\n👁️ Seen on @cibsecurity','\n',char(10)),'🕵️‍♂️ Calling on Cyber Pros to Help Defend City Hall 🕵️‍♂️  Government agencies with smaller budgets need support  and here''s how you can help.','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.darkreading.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:01:19.000Z','2026-08-21 17:36:37','2026-08-21 17:36:37');
