INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_546e9a1b-b67','tg_whackdoor','30726','281b6ecce4dfa2e6e74a7cfa2f5f546c5201248756029aaea959dd7c075ba8f7',replace('**Пожизненное в дурке за сливы GTA VI** — такой срок получил прошлый хакер в 2023 году.\n\nБыстро обрисовываем ситуацию с новыми сливами:\n\n• Анализ ников, постов и сообщений указывает, что **хакер из Германии** — там очень жестокие законы о киберпреступлениях.\n• У хакеров, скорее всего, есть **полностью играбельный билд** — в одном из сливов хакер настрелял свой ник на стене.\n• Хакеры требуют, чтобы Rockstar **публично извинилась** за отмену продажи GTA VI на дисках.\n• Rockstar уже обратилась в суд и требует от Microsoft с Discrod слить вообще все данные хакера — IP, OneDrive, номер телефона, аккаунты и т. д.\n• Это не первый слив — в 2022 году чел слил 90 видосов из ещё даже не анонсированной GTA VI.\n• В 2023 его **приговорили на пожизненное в дурке.**\n\nСейчас о новом хакере неизвестно ничего, но будьте уверены, **Rockstar перевернёт весь мир, чтобы найти его** на дне океана\n\n👍 [Бэкдор](https://t.me/whackdoor?erid=2VtzquZvQkb)','\n',char(10)),'**Пожизненное в дурке за сливы GTA VI** — такой срок получил прошлый хакер в 2023 году. Быстро обрисовываем ситуацию с новыми сливами: • Анализ ников, постов и сообщений указывает, что **хакер из Германии** — там очень жестокие законы о киберпреступлениях. • У хакеров, скорее всего, есть **полностью играбельный билд** — в одном из сливов хакер настрелял свой ник на стене. • Хакеры требуют, чтобы Rockstar **публично извинилась** за отмену продажи GTA VI на дисках. • Rockstar уже обратилась в суд','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-21T17:42:11.000Z','2026-08-21 17:49:45','2026-08-21 17:49:45');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_159bfd8e-e6a','tg_test_channel','9999','56d71c2223fbf11d7339dec50279bd8d7e47ad162ecf7536d7876eaa28ad47b0','?? CRITICAL: New ransomware group ''DarkSide'' targeting Windows servers. CVE-2023-12345 actively exploited. IPs involved: 192.168.1.100.','?? CRITICAL: New ransomware group ''DarkSide'' targeting Windows servers. CVE-2023-12345 actively exploited. IPs involved: 192.168.1.100.','en','{"cves":["CVE-2023-12345"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":["DarkSide"],"malware":[]}','SUCCEEDED','2023-07-22T04:26:40.000Z','2026-08-21 17:49:52','2026-08-21 17:49:52');
